import subprocess, time
from datetime import date, timedelta
from pathlib import Path

START, END = date(2024, 1, 1), date(2024, 2, 29)
MAX_PARALLEL = 3          # concurrency cap (throttling)
SLEEP_BETWEEN = 5         # seconds between launches (pacing)
DONE = Path("backfill_done.log")
completed = set(DONE.read_text().split()) if DONE.exists() else set()

def partitions(start, end):
    d = start
    while d <= end:
        yield d.isoformat()
        d += timedelta(days=1)

running = {}
for ds in partitions(START, END):
    if ds in completed:
        print(f"skip (already done) {ds}"); continue
    # throttle: wait until a slot frees up
    while len(running) >= MAX_PARALLEL:
        for d, p in list(running.items()):
            if p.poll() is not None:
                if p.returncode == 0:
                    with DONE.open("a") as f: f.write(ds_map[d] + "\n")
                    print(f"done {d}")
                else:
                    print(f"FAILED {d} rc={p.returncode}")
                del running[d]
        time.sleep(2)
    # each partition is an idempotent overwrite job
    proc = subprocess.Popen([
        "spark-submit", "--queue", "backfill_queue",  # isolated queue
        "jobs/fact_revenue.py", "--ds", ds, "--mode", "overwrite",
    ])
    ds_map[proc.pid] = ds
    running[proc.pid] = proc
    time.sleep(SLEEP_BETWEEN)

for d, p in running.items():
    p.wait()
    if p.returncode == 0:
        with DONE.open("a") as f: f.write(ds_map[d] + "\n")
print("backfill complete")

